
"use client";

import { useEffect, useState } from "react";
import { words } from "../../data/words";

type Progress = {
  xp: number;
  mastered: number[];
  revision: number[];
};

const STORAGE_KEY = "lexicon-progress";

export default function LearnPage() {
  const [index, setIndex] = useState(0);
  const [revealed, setRevealed] = useState(false);
  const [finished, setFinished] = useState(false);
  const [known, setKnown] = useState(0);
  const [review, setReview] = useState(0);
  const [progress, setProgress] = useState<Progress>({
    xp: 0,
    mastered: [],
    revision: [],
  });
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        setProgress(JSON.parse(saved));
      } catch {
        console.error("Could not load learning progress.");
      }
    }
    setLoaded(true);
  }, []);

  useEffect(() => {
    if (loaded) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(progress));
    }
  }, [progress, loaded]);

  const word = words[index];

  function answer(didKnow: boolean) {
    const wordId = word.id;

    if (didKnow) {
      setKnown((value) => value + 1);
      setProgress((previous) => ({
        xp: previous.xp + 10,
        mastered: previous.mastered.includes(wordId)
          ? previous.mastered
          : [...previous.mastered, wordId],
        revision: previous.revision.filter((id) => id !== wordId),
      }));
    } else {
      setReview((value) => value + 1);
      setProgress((previous) => ({
        ...previous,
        revision: previous.revision.includes(wordId)
          ? previous.revision
          : [...previous.revision, wordId],
        mastered: previous.mastered.filter((id) => id !== wordId),
      }));
    }

    if (index === words.length - 1) {
      setFinished(true);
    } else {
      setIndex((value) => value + 1);
      setRevealed(false);
    }
  }

  function restart() {
    setIndex(0);
    setKnown(0);
    setReview(0);
    setRevealed(false);
    setFinished(false);
  }

  if (!loaded) return null;

  return (
    <main className="min-h-screen px-6 py-10 md:px-12">
      <div className="mx-auto max-w-3xl">
        <a href="/" className="text-sm tracking-widest text-[#95839E]">
          ← LEXICON.
        </a>

        <header className="mb-10 mt-12 text-center">
          <p className="text-xs uppercase tracking-[0.3em] text-[#95839E]">
            The learning studio
          </p>
          <h1 className="font-serif mt-3 text-5xl text-[#373247]">
            The Art of Recall.
          </h1>
          <p className="mt-3 text-sm text-[#95839E]">
            Knowing a word is easy. Remembering it is another matter.
          </p>
        </header>

        <div className="mb-6 grid grid-cols-3 gap-3 text-center">
          <div className="rounded-2xl bg-white/70 p-4">
            <p className="font-serif text-2xl">{progress.xp}</p>
            <p className="mt-1 text-xs text-[#95839E]">Total XP</p>
          </div>
          <div className="rounded-2xl bg-[#EAF0E8] p-4">
            <p className="font-serif text-2xl">{progress.mastered.length}</p>
            <p className="mt-1 text-xs text-[#52634F]">Remembered</p>
          </div>
          <div className="rounded-2xl bg-[#F6EDE9] p-4">
            <p className="font-serif text-2xl">{progress.revision.length}</p>
            <p className="mt-1 text-xs text-[#765B59]">To revise</p>
          </div>
        </div>

        <div className="mb-6 flex justify-between text-sm text-[#75677D]">
          <span>✦ Learning session</span>
          <span>{finished ? words.length : index + 1} / {words.length}</span>
        </div>

        <div className="mb-8 h-2 overflow-hidden rounded-full bg-[#EAE2EC]">
          <div
            className="h-full rounded-full bg-[#B8A3C7] transition-all"
            style={{ width: `${finished ? 100 : ((index + 1) / words.length) * 100}%` }}
          />
        </div>

        {finished ? (
          <section className="rounded-3xl border border-[#E8DFE9] bg-white/70 p-10 text-center shadow-sm">
            <p className="text-xs uppercase tracking-[0.25em] text-[#95839E]">
              Session complete
            </p>
            <h2 className="font-serif mt-5 text-4xl text-[#373247]">
              Quite the vocabulary.
            </h2>
            <div className="my-8 grid grid-cols-2 gap-4">
              <div className="rounded-2xl bg-[#F0EAF3] p-5">
                <p className="font-serif text-4xl">{known}</p>
                <p className="mt-2 text-xs text-[#75677D]">Remembered today</p>
              </div>
              <div className="rounded-2xl bg-[#F6EDE9] p-5">
                <p className="font-serif text-4xl">{review}</p>
                <p className="mt-2 text-xs text-[#75677D]">Needs revision</p>
              </div>
            </div>
            <p className="mb-7 text-sm text-[#75677D]">
              You earned {known * 10} XP this session.
            </p>
            <button
              onClick={restart}
              className="rounded-full bg-[#373247] px-8 py-3 text-sm text-white transition hover:bg-[#62546E]"
            >
              Practise again →
            </button>
          </section>
        ) : (
          <section className="rounded-3xl border border-[#E8DFE9] bg-white/70 p-7 shadow-sm md:p-12">
            <div className="mb-8 flex items-center justify-between">
              <span className="rounded-full bg-[#F0EAF3] px-4 py-2 text-xs text-[#75677D]">
                {word.category}
              </span>
              <span className="text-xs text-[#95839E]">{word.difficulty}</span>
            </div>

            <div className="min-h-64 text-center">
              <p className="text-xs uppercase tracking-[0.25em] text-[#95839E]">
                {revealed ? "The meaning" : "Can you recall this word?"}
              </p>

              <h2 className="font-serif mt-8 break-words text-4xl text-[#373247] md:text-5xl">
                {word.term}
              </h2>

              <p className="mt-3 text-sm text-[#95839E]">
                {word.pronunciation}
              </p>

              {!revealed ? (
                <button
                  onClick={() => setRevealed(true)}
                  className="mt-12 rounded-full border border-[#C9B8D1] px-8 py-3 text-sm text-[#62546E] transition hover:bg-[#F0EAF3]"
                >
                  Reveal meaning
                </button>
              ) : (
                <div className="mt-8 text-left">
                  <p className="text-base leading-8 text-[#373247]">
                    {word.meaning}
                  </p>
                  <div className="mt-6 rounded-2xl bg-[#F8F5EF] p-5">
                    <p className="text-xs uppercase tracking-widest text-[#95839E]">
                      The nuance
                    </p>
                    <p className="mt-2 text-sm leading-7 text-[#62546E]">
                      {word.nuance}
                    </p>
                  </div>
                  <p className="mt-6 text-xs uppercase tracking-widest text-[#95839E]">
                    In a sentence
                  </p>
                  <p className="mt-2 font-serif text-lg italic leading-7 text-[#62546E]">
                    “{word.example}”
                  </p>
                </div>
              )}
            </div>

            {revealed && (
              <div className="mt-10 grid grid-cols-2 gap-3">
                <button
                  onClick={() => answer(false)}
                  className="rounded-full border border-[#D9B9B3] bg-[#F6EDE9] px-4 py-4 text-sm text-[#765B59] transition hover:bg-[#F0DFDA]"
                >
                  ✕ Didn't know
                </button>
                <button
                  onClick={() => answer(true)}
                  className="rounded-full bg-[#EAF0E8] px-4 py-4 text-sm text-[#52634F] transition hover:bg-[#DCE8D9]"
                >
                  ✓ I knew it
                </button>
              </div>
            )}
          </section>
        )}

        <p className="mt-8 text-center text-xs tracking-wide text-[#A495A9]">
          A little pretension never hurt.
        </p>
      </div>
    </main>
  );
}
